    def update(self, *, mesh: str | None = ..., ranges: ArrayLike | None = ..., position: ArrayLike = ...,
            yaw: float = ..., trim: ArrayLike | None = ..., rotation_center: ArrayLike = ...,
            modes: Sequence[str] = ..., center_of_gravity: ArrayLike | None = ...,
            mass: float | Literal['displaced'] | None = ...,
            inertia_input: Literal['components', 'radii_of_gyration'] = ..., Ixx: float = ..., Ixy: float = ...,
            Ixz: float = ..., Iyy: float = ..., Iyz: float = ..., Izz: float = ..., radii_of_gyration: ArrayLike = ...,
            inertia_origin: str | ArrayLike = ..., additional_stiffness: ArrayLike | None = ...,
            additional_damping: ArrayLike | None = ..., stiffness_origin: str | ArrayLike = ...,
            damping_origin: str | ArrayLike = ..., excitation_method: Literal['diffraction', 'haskind'] = ...,
            mode_mass: ArrayLike | None = ..., mode_damping: ArrayLike | None = ...,
            mode_stiffness: ArrayLike | None = ..., body_points: ArrayLike | None = ...,
            body_point_neighbors: int = ...,
            interior_surface: Literal['none', 'detect', 'waterline', 'graded', 'projected', 'mesh'] = ...,
            interior_surface_mesh: str | None = ..., interior_surface_ranges: ArrayLike | None = ...,
            control_surface: Literal['none', 'mesh', 'cylinder', 'ellipsoid', 'automatic'] = ...,
            control_surface_mesh: str | None = ..., control_surface_ranges: ArrayLike | None = ...,
            control_surface_waterline_term: Literal['control_surface', 'body'] = ...,
            control_surface_radius: float | None = ..., control_surface_depth: float | None = ...,
            control_surface_inner_radius: float | None = ..., control_surface_semi_axes: ArrayLike | None = ...,
            control_surface_inner_semi_axes: ArrayLike | None = ...,
            control_surface_outer: Literal['circle', 'polygon'] = ..., control_surface_boundary: ArrayLike | None = ...,
            control_surface_partitions: ArrayLike | None = ..., control_surface_panel_size: float | None = ...,
            enabled: bool = ...) -> None:
        """Sets the items given (and replaces the lists given); the others stay as they are. None
        returns an item to its default.

        Args:
            mesh: The wetted surface: the name of a mesh of the model, body coordinates (with ranges its elements).
                A low-order mesh, or a patch mesh with options.higher_order; with trim the hull, cut at the free surface
                by the engine. Unset: a body of dipoles or of free-surface plates only. Default: unset. The name of an
                object of meshes.
            ranges: The elements of the mesh: [(first, last), ...], one-based ranges of its stored elements, first
                <= last, without overlaps; None: every element. Default: unset.
            position: The global position of the body origin. Unit: m. Default: [0.0, 0.0, 0.0].
            yaw: The rotation of the body about the global z axis, applied before the translation. Unit: deg.
                Default: 0.0.
            trim: The elevation (m), pitch and roll (deg) of the hull in body coordinates: the mesh is moved to x =
                R(pitch, roll) xi + (0, 0, elevation) and every surface of the body cut at the free surface when the
                problem is built (tanks at their own surface level); unset: the meshes are the wetted surfaces as given.
                Default: unset.
            rotation_center: The motion reference point R, body-local: the first-order results (forces, matrices,
                motions) are about R. Unit: m. Default: [0.0, 0.0, 0.0].
            modes: The rigid modes of the body, in order (surge, sway, heave, roll, pitch, yaw): its radiation
                columns and free motions; [] a fixed body that still interacts. Default: [surge, sway, heave, roll,
                pitch, yaw].
            center_of_gravity: The centre of gravity G, body-local; needed for the motions and the weight. Unit: m.
                Default: unset.
            mass: The mass of the body (0 a massless body, such as a light piston or lid, whose inertia is its added
                mass), or displaced: the density times the displaced volume, less the fluid of its tanks. Needed with
                center_of_gravity for the weight, and for the motions. Unit: kg. Default: unset. Or one of: displaced.
            inertia_input: Which inertia is used: components (Ixx ... Izz) or radii_of_gyration; the other is kept
                unused. Default: radii_of_gyration. Choices: components, radii_of_gyration.
            Ixx: The inertia component Ixx about inertia_origin, body axes (read with inertia_input components).
                Unit: kg m^2. Default: 0.0. Used with inertia_input = "components"; kept unused otherwise.
            Ixy: The inertia component Ixy about inertia_origin, body axes, without a sign change. Unit: kg m^2.
                Default: 0.0. Used with inertia_input = "components"; kept unused otherwise.
            Ixz: The inertia component Ixz about inertia_origin, body axes, without a sign change. Unit: kg m^2.
                Default: 0.0. Used with inertia_input = "components"; kept unused otherwise.
            Iyy: The inertia component Iyy about inertia_origin, body axes. Unit: kg m^2. Default: 0.0. Used with
                inertia_input = "components"; kept unused otherwise.
            Iyz: The inertia component Iyz about inertia_origin, body axes, without a sign change. Unit: kg m^2.
                Default: 0.0. Used with inertia_input = "components"; kept unused otherwise.
            Izz: The inertia component Izz about inertia_origin, body axes. Unit: kg m^2. Default: 0.0. Used with
                inertia_input = "components"; kept unused otherwise.
            radii_of_gyration: The radii of gyration about inertia_origin (inertia_input radii_of_gyration), three
                values (the diagonal) or a symmetric 3 x 3 matrix; I = m r |r| with the mass in use. Unit: m. Default:
                [0.0, 0.0, 0.0]. Used with inertia_input = "radii_of_gyration"; kept unused otherwise.
            inertia_origin: The point of the inertia: center_of_gravity, rotation_center or a body-local point.
                Unit: m. Default: center_of_gravity. Or one of: center_of_gravity, rotation_center.
            additional_stiffness: An external 6 x 6 stiffness matrix of the body's rigid modes, about
                stiffness_origin; the coupling to another body is a coupling. Unit: SI. Default: unset.
            additional_damping: An external 6 x 6 damping matrix of the body's rigid modes, about damping_origin;
                the coupling to another body is a coupling. Unit: SI. Default: unset.
            stiffness_origin: The point of additional_stiffness, as inertia_origin. Unit: m. Default:
                rotation_center. Or one of: center_of_gravity, rotation_center.
            damping_origin: The point of additional_damping, as inertia_origin. Unit: m. Default: rotation_center.
                Or one of: center_of_gravity, rotation_center.
            excitation_method: The exciting force in the body's motion equation: by pressure integration of the
                diffraction potential (excitation_diffraction) or by the Haskind relation (excitation_haskind). Default:
                diffraction. Choices: diffraction, haskind.
            mode_mass: The (6 + G) x (6 + G) mass matrix of the rigid (about R) and generalized coordinates; the
                rigid block zero. Unit: SI. Default: unset.
            mode_damping: The (6 + G) x (6 + G) damping matrix of the rigid and generalized coordinates; the rigid
                block zero. Unit: SI. Default: unset.
            mode_stiffness: The (6 + G) x (6 + G) stiffness matrix of the rigid and generalized coordinates; the
                rigid block zero. Unit: SI. Default: unset.
            body_points: Body-local points (N, 3) where the body outputs are given instead of the panels; for every
                body or none. Unit: m. Default: unset.
            body_point_neighbors: Low order with body_points: the number of nearest panel centroids averaged by
                inverse distance at each point. Default: 4.
            interior_surface: The interior surface inside the waterline, which removes the irregular frequencies:
                none; detect, the elements of the wetted surface lying in z = 0 (none if there are none); a surface the
                engine generates: waterline (the regions inside the waterline triangulated; higher order: of a trimmed
                body), graded (a fan from the centroid of each region, graded towards the waterline) or projected (the
                downward-facing wetted elements projected to z = 0); or mesh, a given surface (interior_surface_mesh,
                interior_surface_ranges). Default: detect. Choices: none, detect, waterline, graded, projected, mesh.
            interior_surface_mesh: (mesh) The given interior surface: the name of a mesh, body coordinates, at z = 0
                with upward normals. Default: unset. The name of an object of meshes. Used with interior_surface =
                "mesh"; kept unused otherwise.
            interior_surface_ranges: (mesh) The elements of interior_surface_mesh: [(first, last), ...], one-based
                ranges of its stored elements, first <= last, without overlaps; unset: every element. Default: unset.
                Used with interior_surface = "mesh"; kept unused otherwise.
            control_surface: The control surface of the control-surface drift (needed by
                second_order.drift_control_surface): none; mesh, a given surface (control_surface_mesh,
                control_surface_ranges); or one the engine generates when the problem is built, each with
                control_surface_panel_size: cylinder (radius, depth, inner_radius), ellipsoid (semi_axes,
                inner_semi_axes) or automatic around the body's waterline with its free-surface part (depth, partitions,
                outer with radius or boundary). Default: none. Choices: none, mesh, cylinder, ellipsoid, automatic.
            control_surface_mesh: (mesh) The given control surface: the name of a mesh, body coordinates, around the
                body, normals away from it. Default: unset. The name of an object of meshes. Used with control_surface =
                "mesh"; kept unused otherwise.
            control_surface_ranges: (mesh) The elements of control_surface_mesh: [(first, last), ...], one-based
                ranges of its stored elements, first <= last, without overlaps; unset: every element. Default: unset.
                Used with control_surface = "mesh"; kept unused otherwise.
            control_surface_waterline_term: (every method) Where the control-surface drift takes the zeta^2 term of
                the waterline: control_surface on the waterline of the control surface; body on the body waterline with
                a free-surface integral (a control surface close to the body). Default: control_surface. Choices:
                control_surface, body. Used with control_surface = "mesh", or control_surface = "cylinder", or
                control_surface = "ellipsoid", or control_surface = "automatic"; kept unused otherwise.
            control_surface_radius: (cylinder) The radius of the cylinder; (automatic with outer circle) the radius
                of the circular outer surface about the body origin. Unit: m. Default: unset. Used with control_surface
                = "cylinder", or control_surface = "automatic" with control_surface_outer = "circle"; kept unused
                otherwise.
            control_surface_depth: (cylinder, automatic) The depth of the surface below the free surface. Unit: m.
                Default: unset. Used with control_surface = "cylinder", or control_surface = "automatic"; kept unused
                otherwise.
            control_surface_inner_radius: (cylinder) The radius of the circular waterline inside, where the free
                surface between it and the cylinder begins. Unit: m. Default: unset. Used with control_surface =
                "cylinder"; kept unused otherwise.
            control_surface_semi_axes: (ellipsoid) The semi-axes a, b, c of the lower half-ellipsoid. Unit: m.
                Default: unset. Used with control_surface = "ellipsoid"; kept unused otherwise.
            control_surface_inner_semi_axes: (ellipsoid) The semi-axes of the elliptic waterline inside, where the
                free surface between it and the ellipsoid begins. Unit: m. Default: unset. Used with control_surface =
                "ellipsoid"; kept unused otherwise.
            control_surface_outer: (automatic) The outer surface: a circle (control_surface_radius) or a polygon
                (control_surface_boundary). Default: circle. Choices: circle, polygon. Used with control_surface =
                "automatic"; kept unused otherwise.
            control_surface_boundary: (automatic with outer polygon) The (x, y) vertices of the outer polygon in the
                stored sector, counter-clockwise about the body origin, body coordinates. Unit: m. Default: unset. Used
                with control_surface = "automatic" with control_surface_outer = "polygon"; kept unused otherwise.
            control_surface_partitions: (automatic) Further (x, y) polylines of the free surface, one after the
                other, each ended by a row of NaN (the last may be left open); unset: none. Unit: m. Default: unset.
                Used with control_surface = "automatic"; kept unused otherwise.
            control_surface_panel_size: (cylinder, ellipsoid, automatic) The panel size of the generated surface.
                Unit: m. Default: unset. Used with control_surface = "cylinder", or control_surface = "ellipsoid", or
                control_surface = "automatic"; kept unused otherwise.
            enabled: Whether the solve takes the body with everything under it; false: kept in the model with all
                its items, but solved as if it were absent. Default: true.
        """
        self._update(locals())


