    @property
    def profile(self) -> Literal['linear', 'smooth', 'quadratic_start', 'quadratic_end']:
        """The profile P(t) of the map in v: linear, smooth, quadratic_start, quadratic_end.

        Default: linear. Choices: linear, smooth, quadratic_start, quadratic_end."""
        return self._o.get("profile")

    @profile.setter
    def profile(self, value: Literal['linear', 'smooth', 'quadratic_start', 'quadratic_end']) -> None:
        self._set("profile", value)

    @property
    def a(self) -> float:
        """The horizontal scale of x.

        Unit: m. Default: 1.0."""
        return self._o.get("a")

    @a.setter
    def a(self, value: float) -> None:
        self._set("a", value)

    @property
    def b(self) -> float:
        """The horizontal scale of y.

        Unit: m. Default: 1.0."""
        return self._o.get("b")

    @b.setter
    def b(self, value: float) -> None:
        self._set("b", value)

    @property
    def theta0(self) -> float:
        """The azimuth at u = -1.

        Unit: rad. Default: 0.0."""
        return self._o.get("theta0")

    @theta0.setter
    def theta0(self, value: float) -> None:
        self._set("theta0", value)

    @property
    def theta1(self) -> float:
        """The azimuth at u = 1.

        Unit: rad. Default: 0.0."""
        return self._o.get("theta1")

    @theta1.setter
    def theta1(self, value: float) -> None:
        self._set("theta1", value)

    @property
    def p(self) -> np.ndarray:
        """The four parameters of the kind (line: rho0, z0, rho1, z1; arc: c, phi0, phi1; ellipses: a0, b0, z0, z1;
        segment_arc: z1).

        Default: [0.0, 0.0, 0.0, 0.0]."""
        return self._o.get("p")

    @p.setter
    def p(self, value: ArrayLike) -> None:
        self._set("p", value)

    @property
    def vertices(self) -> np.ndarray | None:
        """bilinear: the four corners; segment_arc: the two ends of the segment.

        Unit: m. Default: unset."""
        return self._o.get("vertices")

    @vertices.setter
    def vertices(self, value: ArrayLike | None) -> None:
        self._set("vertices", value)

    def update(self, *, map: Literal['line', 'arc', 'bilinear', 'ellipses', 'segment_arc'] | None = ...,
            profile: Literal['linear', 'smooth', 'quadratic_start', 'quadratic_end'] = ..., a: float = ...,
            b: float = ..., theta0: float = ..., theta1: float = ..., p: ArrayLike = ...,
            vertices: ArrayLike | None = ...) -> None:
        """Sets the items given (and replaces the lists given); the others stay as they are. None
        returns an item to its default.

        Args:
            map: The map of the patch: line, arc, bilinear, ellipses or segment_arc. Default: unset. Choices: line,
                arc, bilinear, ellipses, segment_arc.
            profile: The profile P(t) of the map in v: linear, smooth, quadratic_start, quadratic_end. Default:
                linear. Choices: linear, smooth, quadratic_start, quadratic_end.
            a: The horizontal scale of x. Unit: m. Default: 1.0.
            b: The horizontal scale of y. Unit: m. Default: 1.0.
            theta0: The azimuth at u = -1. Unit: rad. Default: 0.0.
            theta1: The azimuth at u = 1. Unit: rad. Default: 0.0.
            p: The four parameters of the kind (line: rho0, z0, rho1, z1; arc: c, phi0, phi1; ellipses: a0, b0, z0,
                z1; segment_arc: z1). Default: [0.0, 0.0, 0.0, 0.0].
            vertices: bilinear: the four corners; segment_arc: the two ends of the segment. Unit: m. Default: unset.
        """
        self._update(locals())


