class CouplingList(ObjectList[Coupling]):
    """A list of Coupling objects, indexed by position or by name; its ``add`` takes the items by keyword."""

    __slots__ = ()

    def add(self, name: str | None = None, *, body: str | None = ..., stiffness: ArrayLike | None = ...,
            damping: ArrayLike | None = ..., enabled: bool = ...) -> Coupling:
        """A new Coupling at the end of the list, with the items given (the others at their defaults).

        Args:
            name: The name of the Coupling in the list, unique within it; None: none (found by its position).
            body: The other body, by name (required; not the body itself): the columns are its six rigid motions.
                Default: unset. The name of an object of bodies.
            stiffness: The 6 x 6 stiffness between the bodies: the rows the six forces of this body about its
                stiffness_origin, the columns the six motions of the other body about that body's stiffness_origin.
                Unit: SI. Default: unset.
            damping: The 6 x 6 damping between the bodies: the rows the six forces of this body about its
                damping_origin, the columns the six motions of the other body about that body's damping_origin. Unit:
                SI. Default: unset.
            enabled: Whether the solve takes the coupling (one that names a disabled body is skipped as well);
                false: kept in the model with all its items, but solved as if it were absent. Default: true.
        """
        return self._add(name, locals())


