    def add(self, *, u: ArrayLike = ..., v: ArrayLike = ..., w: ArrayLike = ...,
            ranges: ArrayLike | None = ...) -> ModePiece:
        """A new ModePiece at the end of the list, with the items given (the others at their defaults).

        Args:
            u: The terms c x^px y^py z^pz of the x displacement, as rows (c, px, py, pz), body-local. Unit: m.
                Default: empty.
            v: The terms of the y displacement, as u. Unit: m. Default: empty.
            w: The terms of the z displacement, as u. Unit: m. Default: empty.
            ranges: The elements of the body's mesh where the piece applies: [(first, last), ...], one-based ranges
                of its stored elements; unset: every element. Default: unset.
        """
        return self._add(None, locals())


